quizzes.explanation:
深くネストされた構造で親の state を孫へ渡す場合は、Props drilling を避けるため Context API が有力です。Redux などの状態管理ツールは、より広域で複雑な共有状態がある場合の選択肢であり、この問いの第一回答ではありません。React.memo は再レンダリング最適化の手段であり、state の受け渡し方法そのものではありません。

浅いツリーの場合の具体コード:
function Parent() {
  const [count, setCount] = useState(0)
  return <Child count={count} setCount={setCount} />
}

function Child({ count, setCount }) {
  return <GrandChild count={count} setCount={setCount} />
}

function GrandChild({ count, setCount }) {
  return <button onClick={() => setCount(count + 1)}>{count}</button>
}

深いツリーの場合の具体コード:
const CountContext = createContext(null)

function Parent() {
  const [count, setCount] = useState(0)
  return (
    <CountContext.Provider value={{ count, setCount }}>
      <Child />
    </CountContext.Provider>
  )
}

function GrandChild() {
  const { count, setCount } = useContext(CountContext)
  return <button onClick={() => setCount(count + 1)}>{count}</button>
}

複雑状態での具体コード:
const useQuizStore = create((set) => ({
  count: 0,
  selectedIds: [],
  increment: () => set((state) => ({ count: state.count + 1 })),
  toggleSelected: (id) =>
    set((state) => ({
      selectedIds: state.selectedIds.includes(id)
        ? state.selectedIds.filter((item) => item !== id)
        : [...state.selectedIds, id],
    })),
}))

function GrandChild() {
  const count = useQuizStore((state) => state.count)
  const increment = useQuizStore((state) => state.increment)
  return <button onClick={increment}>{count}</button>
}

